mapper.select:
select  from topic_route_session
where member_id=#{memberId} and topic_id=#{topicId}
and id < #{beforeSessionId}
order by id desc limit #{limit}

select  from topic_route_session
where activity_id=#{activityId} and topic_id=#{topicId} and member_id=#{memberId}
  and play_instance_id=#{playInstanceId} limit 1

mapper.update:
update topic_route_session set state_json=#{stateJson},status=#{status},current_node_id=#{currentNodeId},
  recommended_node_id=#{recommendedNodeId},completed_at=#{completedAt},version=version+1,update_time=#{updateTime}
where id=#{id} and member_id=#{memberId} and version=#{version} and status=0
